<?php
namespace App\Core;
class Model { protected string $table; protected function db(){return Database::pdo();} public function all(string $where='1',array $params=[]): array {$s=$this->db()->prepare("select * from {$this->table} where {$where}");$s->execute($params);return $s->fetchAll();} public function find(int $id): ?array {$s=$this->db()->prepare("select * from {$this->table} where id=?");$s->execute([$id]);return $s->fetch()?:null;} public function create(array $data): int {$cols=array_keys($data);$sql="insert into {$this->table} (".implode(',',$cols).") values (".implode(',',array_fill(0,count($cols),'?')).")";$s=$this->db()->prepare($sql);$s->execute(array_values($data));return (int)$this->db()->lastInsertId();} public function update(int $id,array $data): void {$set=implode(',',array_map(fn($c)=>"$c=?",array_keys($data)));$this->db()->prepare("update {$this->table} set $set where id=?")->execute([...array_values($data),$id]);} }
